# Independent check: integer lattice generated by the y-smooth elements of S (digits in D, <= L digits).
# Incremental Hermite normal form (row echelon over Z). Reports which primes <= y lie in the subgroup
# generated by those smooth elements (a lower bound for G ∩ primes), and the index structure.
import sys, itertools, numpy as np
D=[int(c) for c in sys.argv[1]]; L=int(sys.argv[2]); y=int(sys.argv[3])
pr=[p for p in range(2,y+1) if all(p%q for q in range(2,int(p**.5)+1))]; n=len(pr)
vals=[]
for l in range(1,L+1):
    for t in itertools.product(D,repeat=l): vals.append(int(''.join(map(str,t))))
v=np.array(vals,dtype=np.uint64); E=np.zeros((len(v),n),np.int64); r=v.copy()
for j,p in enumerate(pr):
    P=np.uint64(p)
    while True:
        m=(r%P==0)
        if not m.any(): break
        r[m]//=P; E[m,j]+=1
sm=np.nonzero(r==1)[0]; print(f'D={sys.argv[1]} L={L} y={y}: |S|={len(v)}, y-smooth elements {len(sm)} (excluding 1)')
H={}  # pivot col -> row (python int lists)
def egcd(a,b):
    if b==0: return (a,1,0) if a>=0 else (-a,-1,0)
    g,x,y_=egcd(b,a%b); return g,y_,x-(a//b)*y_
def insert(w):
    w=list(map(int,w))
    for j in range(n):
        if w[j]==0: continue
        if j not in H:
            if w[j]<0: w=[-x for x in w]
            H[j]=w; return
        h=H[j]; a,b=h[j],w[j]; g,x,y_=egcd(a,b)
        newh=[x*h[k]+y_*w[k] for k in range(n)]; w=[(a//g)*w[k]-(b//g)*h[k] for k in range(n)]
        H[j]=newh
    return
for i in sm:
    if v[i]==1: continue
    insert(E[i])
    if len(H)==n and all(H[j][j]==1 for j in H): break
diag={pr[j]:H[j][j] for j in H}
missing=[p for p in pr if pr.index(p) not in H]
print('rank',len(H),'of',n,'; columns with no pivot (prime unconstrained):',missing[:20])
# reduce to find which unit vectors are in lattice: back-substitute (full HNF) then e_p in L iff row for p is unit
cols=sorted(H)
for j in reversed(cols):
    for i in cols:
        if i<j and H[i][j]!=0:
            q=H[i][j]//H[j][j]; H[i]=[H[i][k]-q*H[j][k] for k in range(n)]
inG=[]
for p in pr:
    j=pr.index(p); e=[0]*n; e[j]=1; ok=True
    for c in cols:
        if e[c]%H[c][c]: ok=False;break
        q=e[c]//H[c][c]
        if q: e=[e[k]-q*H[c][k] for k in range(n)]
    if ok and not any(e): inG.append(p)
print('primes <= y proven in G (from smooth elements):',len(inG),'of',n)
print('not proven:',[p for p in pr if p not in inG][:40])
print('diagonal entries !=1:',{p:d for p,d in diag.items() if d!=1})
